SELECT CAST(COUNT(DISTINCT CASE WHEN p.starttime BETWEEN 0 AND 24 THEN e.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN p.starttime BETWEEN 24 AND 36 THEN e.subject_id END), 0) AS proportion FROM patients p JOIN emar e ON p.subject_id = e.subject_id JOIN prescriptions pr ON p.subject_id = pr.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 75 AND 85 AND pr.drug_type = 'injectable' AND pr.drug = 'GLP-1' AND pr.route = 'intravenous';